"use client"

import * as React from "react"
import { ScrollArea as ScrollAreaPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { scrollThumbRecipe, type ScrollThumbOrientation } from "@/lib/ink/recipes/scroll-area-ink"
import { cn } from "@/lib/utils"

function ScrollArea({
  className,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Root>) {
  return (
    <ScrollAreaPrimitive.Root
      data-slot="scroll-area"
      ref={ref}
      className={cn("relative overflow-hidden", className)}
      {...props}
    >
      <ScrollAreaViewport>{children}</ScrollAreaViewport>
      <ScrollBar />
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  )
}

function ScrollBar({
  className,
  orientation = "vertical",
  seed,
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Scrollbar> & { seed?: string | number }) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      data-slot="scroll-area-scrollbar"
      orientation={orientation}
      className={cn(
        "flex touch-none p-0.5 transition-colors select-none",
        orientation === "vertical" && "h-full w-2.5 border-l border-transparent",
        orientation === "horizontal" && "h-2.5 flex-col border-t border-transparent",
        className,
      )}
      {...props}
    >
      <ScrollThumb orientation={orientation === "horizontal" ? "horizontal" : "vertical"} seed={seed} />
    </ScrollAreaPrimitive.Scrollbar>
  )
}

function ScrollThumb({
  orientation,
  seed,
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Thumb> & {
  orientation: ScrollThumbOrientation
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({
    recipe: scrollThumbRecipe,
    params: { orientation },
    kind: "scroll-thumb",
    seed,
    still: true,
  })

  return (
    <ScrollAreaPrimitive.Thumb
      data-slot="scroll-area-thumb"
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      className={cn("relative isolate rounded-full bg-transparent", className)}
      {...props}
    >
      {node}
    </ScrollAreaPrimitive.Thumb>
  )
}

function ScrollAreaViewport({ className, ref, ...props }: React.ComponentProps<typeof ScrollAreaPrimitive.Viewport>) {
  return (
    <ScrollAreaPrimitive.Viewport
      data-slot="scroll-area-viewport"
      ref={ref}
      className={cn("size-full rounded-[inherit] outline-none", className)}
      {...props}
    />
  )
}

export { ScrollArea, ScrollAreaViewport, ScrollBar }

import { wash } from '@/lib/ink/fills'
import { pillPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type ScrollThumbOrientation = 'vertical' | 'horizontal'

export interface ScrollThumbParams {
  orientation: ScrollThumbOrientation
}

export const scrollThumbRecipe = defineRecipe<ScrollThumbParams>({
  id: 'scroll-thumb',
  kind: 'scroll-thumb',
  layers: ['rest', 'hover'],
  pad: 4,
  draw(ink, { w, h }, { orientation }) {
    const vertical = orientation === 'vertical'
    const body = vertical
      ? pillPoly(Math.max(0, w / 2 - 1.5), 0.5, Math.min(w - 1, 3), Math.max(2, h - 1))
      : pillPoly(0.5, Math.max(0, h / 2 - 1.5), Math.max(2, w - 1), Math.min(h - 1, 3))

    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-shade', alpha: 0.38, wobble: 0.42 },
        { color: 'rose-wash', alpha: 0.22, inset: 0.45 },
      ])
      if (Math.max(w, h) > 6) {
        box(ink, 0.4, 0.4, w - 0.8, h - 0.8, {
          pen: 'pencil.fine',
          corner: vertical ? 1.5 : 1.5,
          loose: 0.4,
          opts: { alpha: 0.35, simple: true, color: 'line-soft' },
        })
      }
    })

    ink.layer('hover', () => {
      wash(ink, body, 'horizon', { alpha: 0.28, material: 'wash', wobble: 0.55 })
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
